// Text measurement without a browser canvas, from the advance widths of the
// same fonts Excalidraw renders with (generated by scripts/build.mjs).
import { readFileSync } from 'node:fs'
import { DEFAULT_FONT_FAMILY } from '../shared/fonts.js'

const METRICS = JSON.parse(readFileSync(new URL('../../assets/font-metrics.json', import.meta.url), 'utf8'))

const WIDE_RANGES = [
  [0x1100, 0x115f], [0x2e80, 0x303e], [0x3041, 0x33ff], [0x3400, 0x4dbf], [0x4e00, 0x9fff],
  [0xa000, 0xa4cf], [0xac00, 0xd7a3], [0xf900, 0xfaff], [0xfe30, 0xfe4f], [0xff00, 0xff60],
  [0xffe0, 0xffe6], [0x1f300, 0x1faff], [0x20000, 0x3fffd],
]

function isWide(code) {
  return WIDE_RANGES.some(([start, end]) => code >= start && code <= end)
}

function charWidth(code, metrics, fontSize) {
  const advance = metrics.advances[code]
  if (advance !== undefined) return advance / metrics.unitsPerEm * fontSize
  if (isWide(code)) return fontSize
  return metrics.averageAdvance / metrics.unitsPerEm * fontSize
}

export function lineWidth(line, fontFamily, fontSize) {
  const metrics = METRICS[fontFamily] ?? METRICS[DEFAULT_FONT_FAMILY]
  let width = 0
  for (const char of line) width += charWidth(char.codePointAt(0), metrics, fontSize)
  return width
}

/** Width and height of a (possibly multi-line) text, as Excalidraw's `measureText`. */
export function measureText(text, fontFamily, fontSize, lineHeight) {
  const lines = text.split('\n')
  const width = Math.max(0, ...lines.map(line => lineWidth(line, fontFamily, fontSize)))
  return { width: Math.ceil(width * 100) / 100, height: lines.length * fontSize * lineHeight }
}

function tokens(line) {
  // Words stay whole; CJK characters may break anywhere.
  return line.match(/[ᄀ-ᅟ⺀-〾ぁ-㏿㐀-鿿가-힣豈-﫿＀-￯]|\s+|[^\sᄀ-ᅟ⺀-〾ぁ-㏿㐀-鿿가-힣豈-﫿＀-￯]+/gu) ?? []
}

/** Wrap text to `maxWidth`, as Excalidraw does for text bound to a container. */
export function wrapText(text, fontFamily, fontSize, maxWidth) {
  if (!Number.isFinite(maxWidth) || maxWidth <= 0) return text
  const out = []
  for (const original of text.split('\n')) {
    if (lineWidth(original, fontFamily, fontSize) <= maxWidth) {
      out.push(original)
      continue
    }
    let current = ''
    const flush = () => {
      out.push(current.trimEnd())
      current = ''
    }
    for (const token of tokens(original)) {
      if (lineWidth(current + token, fontFamily, fontSize) <= maxWidth) {
        current += token
        continue
      }
      if (/^\s+$/u.test(token)) {
        flush()
        continue
      }
      if (current.trim()) flush()
      if (lineWidth(token, fontFamily, fontSize) <= maxWidth) {
        current = token
        continue
      }
      for (const char of token) {
        if (current && lineWidth(current + char, fontFamily, fontSize) > maxWidth) flush()
        current += char
      }
    }
    if (current) out.push(current.trimEnd())
  }
  return out.join('\n')
}
